insert into public.processes(codigo_proceso,area_id,tipo_proceso_id,nombre_proceso,responsable_principal,responsable_secundario,fecha_inicio,fecha_fin_programada,fecha_fin_real,estado_id,prioridad_id,porcentaje_avance,dependencia_externa,documento_respaldo,proxima_accion,objetivo,observaciones,fecha_proxima_revision,requiere_accion_gerencial,confidencialidad,activo,created_at,updated_at) values ('TRV-2026-0044',(select id from public.areas where nombre='Sin entidad actual' limit 1),(select id from public.process_types where nombre='Trámite Vario' limit 1),'CENTRO DE EXPOSICIONES PARQUE INDUSTRIAL','Ing. Juan Diego Remache',null,'2026-06-05','2026-06-05',null,(select id from public.process_statuses where nombre='En Ejecución' limit 1),(select id from public.priorities where nombre='Alta' limit 1),45,'Sin entidad actual',null,'Clave catastral 060102006006010029000000000 INGENIERO CESAR CORONEL - 0987427605','Recuperar un bien municipal','Fecha límite original no estructurada: REVISIÓN ING',null,true,'Interna',true,'2026-07-08T00:00:00Z','2026-07-08T00:00:00Z') on conflict (codigo_proceso) do update set area_id=excluded.area_id, tipo_proceso_id=excluded.tipo_proceso_id, nombre_proceso=excluded.nombre_proceso, responsable_principal=excluded.responsable_principal, responsable_secundario=excluded.responsable_secundario, fecha_inicio=excluded.fecha_inicio, fecha_fin_programada=excluded.fecha_fin_programada, fecha_fin_real=excluded.fecha_fin_real, estado_id=excluded.estado_id, prioridad_id=excluded.prioridad_id, porcentaje_avance=excluded.porcentaje_avance, dependencia_externa=excluded.dependencia_externa, documento_respaldo=excluded.documento_respaldo, proxima_accion=excluded.proxima_accion, objetivo=excluded.objetivo, observaciones=excluded.observaciones, fecha_proxima_revision=excluded.fecha_proxima_revision, requiere_accion_gerencial=excluded.requiere_accion_gerencial, confidencialidad=excluded.confidencialidad, activo=excluded.activo, updated_at=excluded.updated_at;
